Here's a class from our reporting pipeline. It works, but it's getting hard to change and hard to test. Can you review its design and tell me what should be improved and how?

```python
import csv
import json
import statistics

class ReportProcessor:
    def __init__(self, input_path, output_path):
        self.input_path = input_path
        self.output_path = output_path

    def run(self):
        data = self._load()
        stats = self._compute(data)
        text = self._format(stats)
        self._save(text)

    def _load(self):
        with open(self.input_path) as f:
            return list(csv.DictReader(f))

    def _compute(self, rows):
        values = [float(r['amount']) for r in rows if r['amount']]
        return {
            'count': len(values),
            'mean': statistics.mean(values),
            'total': sum(values),
        }

    def _format(self, stats):
        return json.dumps(stats, indent=2)

    def _save(self, text):
        with open(self.output_path, 'w') as f:
            f.write(text)
```

We're about to add several new payment methods, and every time we do it feels like we have to touch the same method in a dozen careful places. Can you review this payment processing code and tell me what design changes would make adding new methods easier?

```python
class PaymentProcessor:
    def process(self, payment_type, amount):
        if payment_type == 'credit_card':
            fee = amount * 0.03
            return amount - fee, 'charged card'
        elif payment_type == 'paypal':
            fee = amount * 0.04
            return amount - fee, 'charged paypal'
        elif payment_type == 'bank_transfer':
            fee = amount * 0.01
            return amount - fee, 'charged bank'
        else:
            raise ValueError(f'Unknown payment type: {payment_type}')

    def refund(self, payment_type, amount):
        if payment_type == 'credit_card':
            return amount * 0.97
        elif payment_type == 'paypal':
            return amount * 0.96
        elif payment_type == 'bank_transfer':
            return amount * 0.99
        else:
            raise ValueError(f'Unknown payment type: {payment_type}')
```

